def _get_response_class_from_data(d: dict[str, Any]) -> type[Response]:
    """Get response class from response data."""
    from scrapy.http import HtmlResponse, Response, TextResponse

    if "body" in d:
        if "headers" in d and b"Content-Type" in d["headers"]:
            content_type = d["headers"][b"Content-Type"][0]
            if b"text/html" in content_type:
                return HtmlResponse
            elif b"text/" in content_type:
                return TextResponse
        return TextResponse
